from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class SpecializedScenario(BaseScenario):
    name = 'specialized'
    description = 'Specialized artifact tools (hypotheses, evidence, chains, challenges)'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='get_hypotheses_basic', tool='get_hypotheses', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [3, 3], 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Get all 3 hypotheses for binder_001'), TestCase(name='get_hypotheses_min_score', tool='get_hypotheses', params={'binder_id': 'binder_001', 'min_score': 0.5}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 2]}, description='Get hypotheses with score >= 0.5'), TestCase(name='get_hypotheses_by_source', tool='get_hypotheses', params={'binder_id': 'binder_001', 'source': 'pattern'}, expected={'is_array': True, 'error': False}, description='Get hypotheses filtered by pattern source'), TestCase(name='get_hypotheses_limited', tool='get_hypotheses', params={'binder_id': 'binder_001', 'limit': 2}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 2]}, description='Get hypotheses with limit 2'), TestCase(name='get_hypotheses_binder_002', tool='get_hypotheses', params={'binder_id': 'binder_002'}, expected={'is_array': True, 'error': False, 'array_length_range': [2, 2]}, description='Get 2 hypotheses for binder_002'), TestCase(name='get_evidence_basic', tool='get_evidence', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [4, 4], 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Get all 4 evidence items for binder_001'), TestCase(name='get_evidence_by_type', tool='get_evidence', params={'binder_id': 'binder_001', 'evidence_type': 'code'}, expected={'is_array': True, 'error': False}, description="Get evidence filtered by type 'code'"), TestCase(name='get_evidence_by_strength', tool='get_evidence', params={'binder_id': 'binder_001', 'strength': 'STRONG'}, expected={'is_array': True, 'error': False}, description='Get STRONG evidence items'), TestCase(name='get_evidence_limited', tool='get_evidence', params={'binder_id': 'binder_001', 'limit': 2}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 2]}, description='Get evidence with limit 2'), TestCase(name='get_causal_chains_basic', tool='get_causal_chains', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [2, 2], 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Get 2 causal chains for binder_001'), TestCase(name='get_causal_chains_by_hypothesis', tool='get_causal_chains', params={'binder_id': 'binder_001', 'hypothesis_id': 'hyp_001'}, expected={'is_array': True, 'error': False}, description='Get causal chains for specific hypothesis'), TestCase(name='get_causal_chains_limited', tool='get_causal_chains', params={'binder_id': 'binder_001', 'limit': 1}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 1]}, description='Get causal chains with limit 1'), TestCase(name='get_challenges_basic', tool='get_challenges', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [2, 2], 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Get 2 challenges for binder_001'), TestCase(name='get_challenges_unresolved', tool='get_challenges', params={'binder_id': 'binder_001', 'resolved': False}, expected={'is_array': True, 'error': False}, description='Get unresolved challenges'), TestCase(name='get_challenges_by_severity', tool='get_challenges', params={'binder_id': 'binder_001', 'severity': 'HIGH'}, expected={'is_array': True, 'error': False}, description='Get HIGH severity challenges'), TestCase(name='get_challenges_limited', tool='get_challenges', params={'binder_id': 'binder_001', 'limit': 1}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 1]}, description='Get challenges with limit 1')]